  const sourceFile = program.getSourceFile(inputPath);
  const docNode = sourceFile.getChildren()[0].getChildren()[0].getChildren()[4].getChildren()[0].getChildren()[0].getChildren()[0];

  for (const child of docNode.getChildren()) {
